import React, { useState } from 'react';
import { Link } from 'react-router-dom';

const Home = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [activeFaq, setActiveFaq] = useState(null);

  const toggleFaq = (index) => {
    setActiveFaq(activeFaq === index ? null : index);
  };

  const faqItems = [
    {
      question: "Como cadastrar um motorista?",
      answer: "Acesse a página de cadastro, preencha os dados do motorista e clique em 'Cadastrar'."
    },
    {
      question: "Posso buscar motoristas por placa?",
      answer: "Sim, utilize a página 'Buscar Motorista' e digite a placa desejada."
    },
    {
      question: "Quem pode acessar o sistema?",
      answer: "Apenas usuários autorizados com login e senha."
    }
  ];

  return (
    <div className="home-container">
      {/* Navbar */}
      <nav className="navbar">
        <div className="navbar-brand">
          <span>🚗 CheckPort</span>
          <button 
            className="hamburger" 
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            aria-label="Menu"
          >
            ☰
          </button>
        </div>
        <div className={`nav-links ${isMenuOpen ? 'active' : ''}`}>
          <Link to="/">Início</Link>
          <Link to="/listar">Lista</Link>
          <Link to="/buscar">Buscar</Link>
          <Link to="/login">Login</Link>
        </div>
      </nav>

      {/* Hero Section */}
      <section className="hero">
        <div className="hero-text">
          <h1>Controle de Entrada de Veículos</h1>
          <p className="subtitle">Solução eficiente para gestão de motoristas e acessos.</p>
          <button className="cta-button">Comece Agora</button>
        </div>
        <div className="hero-image">
          <img 
            src="https://placehold.co/600x400/8db986/white?text=CheckPort" 
            alt="Ilustração de veículos" 
          />
        </div>
      </section>

      {/* FAQ Section */}
      <section className="faq-section">
        <h2>Perguntas Frequentes</h2>
        <div className="faq-list">
          {faqItems.map((item, index) => (
            <div 
              key={index} 
              className={`faq-item ${activeFaq === index ? 'active' : ''}`}
              onClick={() => toggleFaq(index)}
            >
              <div className="faq-question">
                {item.question}
                <span className="faq-icon">{activeFaq === index ? '−' : '+'}</span>
              </div>
              {activeFaq === index && (
                <div className="faq-answer">{item.answer}</div>
              )}
            </div>
          ))}
        </div>
      </section>

      {/* Footer */}
      <footer className="footer">
        <div className="footer-links">
          <Link to="/politica">Política de Privacidade</Link>
          <Link to="/termos">Termos de Uso</Link>
          <Link to="/contato">Contato</Link>
        </div>
        <p>© {new Date().getFullYear()} CheckPort. Todos os direitos reservados.</p>
      </footer>
    </div>
  );
};

export default Home;
